    {
      "service": "ts-travel2-service",
      "fault_kind": "pod_failure",
      "evidence": [
        {"kind": "metric", "sql": "SELECT attr_k8s_pod_name pod, min(value) mn, max(value) mx, count(*) n FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'ts-travel2-service%' GROUP BY 1", "claim": "Travel2 pod restart counter reads 1 during the incident window, versus 0 in the normal period."},
        {"kind": "trace", "sql": "SELECT min(time) first_span, max(time) last_span, count(*) n FROM abnormal_traces WHERE service_name='ts-travel2-service'", "claim": "Travel2 emitted no spans for about 43 seconds after the window start (first span 23:03:26, others from 23:02:43), then recovered."},
        {"kind": "trace", "sql": "SELECT service_name, min(time) first_t FROM abnormal_traces WHERE service_name IN ('ts-travel2-service','ts-route-plan-service','ts-travel-plan-service','ts-ui-dashboard') GROUP BY 1", "claim": "Other services start emitting at 23:02:43 while travel2 starts only at 23:03:26."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [
      {"kind": "log", "sql": "SELECT service_name, message, count(*) n FROM abnormal_logs WHERE level='SEVERE' AND service_name='ts-route-plan-service' GROUP BY 1,2", "claim": "Route-plan logs 64 SEVERE 503 errors: upstream connect refused, matching travel2's outage window."}
    ]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [
      {"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, c.attr_http_response_status_code code, count(*) n FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-route-plan-service' AND c.attr_status_code='Error' AND p.service_name='ts-travel-plan-service' GROUP BY ALL", "claim": "Travel-plan's calls to route-plan's minStopStations fail with 503 from route-plan, 64 times."}
    ]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [
      {"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, c.attr_http_response_status_code code, count(*) n FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-travel-plan-service' AND c.attr_status_code='Error' AND p.service_name='ts-ui-dashboard' GROUP BY ALL", "claim": "Ui-dashboard's POST minStation calls to travel-plan return HTTP 500 errors, 4 times in the window."}
    ]}
  ]
}
